    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     * targets: a plot handle, { handle, method }, a function(fn, src), or an array.
     * opts   : { variables=['x'], onChange(fn, src) }
     * On a parse error the last good geometry is kept and the message is shown
     * inline. This NEVER substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_2d.html.
     */
    function bindEquationInput(inputId, targets, opts = {}) {
      const input = document.getElementById(inputId);
      if (!input) throw new Error(`bindEquationInput: no element with id "${inputId}"`);
      const vars = opts.variables || ['x'];
      const list = Array.isArray(targets) ? targets : [targets];
      const slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      const appliers = list.map((t) => _resolveEqTarget(inputId, t));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          const fn = compileExpr(src, vars);
          for (const run of appliers) run(fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', () => apply(input.value));
      apply(input.value);
      return { apply, input, errorSlot: slot };
    }

    /* ── 3D plotting ─────────────────────────────────────────────────────── */
    const _plot3d = new Map();

    function _disposeObject(obj) {
      obj.traverse?.(o => {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
        else o.material?.dispose?.();
      });
    }

    function _register3d(id, handle) {
      const prev = _plot3d.get(id);
      if (prev && prev !== handle) { scene.remove(prev.object); _disposeObject(prev.object); }
      _plot3d.set(id, handle);
      return handle;
    }

    function _resolveFn3d(value, vars) {
      return typeof value === 'function' ? value : compileExpr(value, vars);
    }

    /**
     * plotCurve3D(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain=[-2,2], plane='xy'|'xz',
     *           samples=200, color=0x1f77b4 }
     * 'xy' maps t → (t, f(t), 0); 'xz' maps t → (t, 0, f(t)).
     */
    function plotCurve3D(id, opts = {}) {
      const vars = opts.variables || ['x'];
      const material = new THREE.LineBasicMaterial({ color: opts.color ?? 0x1f77b4 });
      const line = new THREE.Line(new THREE.BufferGeometry(), material);
      scene.add(line);
      const handle = {
        id,
        object: line,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || [-2, 2],
        samples: opts.samples || 200,
        plane: opts.plane === 'xz' ? 'xz' : 'xy',
        setExpr(src) { this.fn = _resolveFn3d(src, vars); return this.sample(); },
        setFn(f) { this.fn = f; return this.sample(); },
        setDomain(dm) { this.domain = dm; return this.sample(); },
        remove() { scene.remove(line); _disposeObject(line); _plot3d.delete(id); },
        sample() {
          if (!this.fn) return this;
          const [a, b] = this.domain;
          const n = Math.max(2, this.samples | 0);
          const pts = [];
          for (let i = 0; i < n; i++) {
            const t = a + (b - a) * (i / (n - 1));
            let v;
            try { v = this.fn(t); } catch { v = NaN; }
            if (!Number.isFinite(v)) v = 0;
            pts.push(this.plane === 'xz' ? new THREE.Vector3(t, 0, v)
              : new THREE.Vector3(t, v, 0));
          }
          const old = line.geometry;
          line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    /**
     * plotParametric3D(id, opts) → handle
     *   opts: { x, y, z, variables=['t'], tDomain=[0,1], samples=200, color }
     */
    function plotParametric3D(id, opts = {}) {
      const vars = opts.variables || ['t'];
      const material = new THREE.LineBasicMaterial({ color: opts.color ?? 0x1f77b4 });
      const line = new THREE.Line(new THREE.BufferGeometry(), material);
      scene.add(line);
      const handle = {
        id,
        object: line,
        fx: _resolveFn3d(opts.x ?? '0', vars),
        fy: _resolveFn3d(opts.y ?? '0', vars),
        fz: _resolveFn3d(opts.z ?? '0', vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX(src) { this.fx = _resolveFn3d(src, vars); return this.sample(); },
        setY(src) { this.fy = _resolveFn3d(src, vars); return this.sample(); },
        setZ(src) { this.fz = _resolveFn3d(src, vars); return this.sample(); },
        remove() { scene.remove(line); _disposeObject(line); _plot3d.delete(id); },
        sample() {
          const [a, b] = this.tDomain;
          const n = Math.max(2, this.samples | 0);
          const pts = [];
          for (let i = 0; i < n; i++) {
            const t = a + (b - a) * (i / (n - 1));
            let x, y, z;
            try { x = this.fx(t); y = this.fy(t); z = this.fz(t); } catch { x = y = z = NaN; }
            if (Number.isFinite(x) && Number.isFinite(y) && Number.isFinite(z)) {
              pts.push(new THREE.Vector3(x, y, z));
            }
          }
          const old = line.geometry;
          line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    /**
     * plotSurface(id, opts) → handle
     *   opts: { expr | fn, variables=['x','y'], xDomain=[-2,2], yDomain=[-2,2],
     *           segments=48, color=0x6699cc, wireframe=false }
     * Height is mapped to the world Y axis (the scaffold is y-up); the domain
     * spans world X and Z.
     */
    function plotSurface(id, opts = {}) {
      const vars = opts.variables || ['x', 'y'];
      const material = new THREE.MeshBasicMaterial({
        color: opts.color ?? 0x6699cc,
        wireframe: !!opts.wireframe,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: opts.opacity ?? 0.85,
      });
      const mesh = new THREE.Mesh(new THREE.BufferGeometry(), material);
      scene.add(mesh);
      const handle = {
        id,
        object: mesh,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        xDomain: opts.xDomain || [-2, 2],
        yDomain: opts.yDomain || [-2, 2],
        segments: opts.segments || 48,
        setExpr(src) { this.fn = _resolveFn3d(src, vars); return this.sample(); },
        setFn(f) { this.fn = f; return this.sample(); },
        remove() { scene.remove(mesh); _disposeObject(mesh); _plot3d.delete(id); },
        sample() {
          if (!this.fn) return this;
          const [x0, x1] = this.xDomain;
          const [y0, y1] = this.yDomain;
          const seg = Math.max(1, this.segments | 0);
          const geom = new THREE.PlaneGeometry(x1 - x0, y1 - y0, seg, seg);
          const pos = geom.attributes.position;
          const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
          for (let i = 0; i < pos.count; i++) {
            const px = pos.getX(i) + cx;
            const py = pos.getY(i) + cy;
            let h;
            try { h = this.fn(px, py); } catch { h = NaN; }
            if (!Number.isFinite(h)) h = 0;
            pos.setXYZ(i, px, h, py);
          }
          pos.needsUpdate = true;
          geom.computeVertexNormals();
          geom.computeBoundingBox();
          geom.computeBoundingSphere();
          const old = mesh.geometry;
          mesh.geometry = geom;
          old?.dispose?.();
          return this;
        }
      };
      return _register3d(id, handle).sample();
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();

  </script>
</body>

</html>
--------------------------------------------------------------------------------

WHAT THE SCAFFOLD PROVIDES (already defined — use these, never re-declare them):
- Scale guide (orthographic camera, d=3 frustum half-height): keep main geometry within ±2 units in all axes. Typical sizes: cube side 1–2 units, arrow length 1–2, plane width 2–4, sphere radius 0.05–0.15.
- setCameraView({ projection, azimuthDeg, elevationDeg, rollDeg, axisScreenAngles, obliqueAngleDeg, depthScale, zoom, target, heightFraction, distanceScale }) — source-matched camera setup.
  heightFraction: fraction of viewport height the content should fill (default 0.5; use 0.65–0.75 to fill more). Omit zoom — the scaffold auto-fits from projected scene bounds.
  Call it AFTER all geometry is in the scene, or auto-fit measures the wrong bounds. Labels come afterwards and do not affect the fit.
- #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel.
- addLabel(htmlString, THREE.Vector3, options?) — floating HTML label system.
- registerInteractive(object, { title, body, tooltip }), showPopup(title, body), hidePopup, showTooltip, hideTooltip — hover/click explanations.
- compileExpr(src, vars) → f(...args); throws on a bad expression (never returns a fallback)
- bindEquationInput(inputId, targets, { variables, onChange }) — wires an <input> to plot handles; shows parse errors inline
- plotCurve3D(id, { expr, variables, domain, plane:'xy'|'xz', samples, color }) → handle
- plotParametric3D(id, { x, y, z, variables, tDomain, samples, color }) → handle
- plotSurface(id, { expr, variables, xDomain, yDomain, segments, color }) → handle
  variables: the argument names the expression may use, in order (defaults: plotCurve3D ['x'], plotParametric3D ['t'], plotSurface ['x','y']). When a plan field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotCurve3D('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  Handles re-sample on EVERY setter call, and the setters differ: plotCurve3D → .setExpr / .setFn / .setDomain · plotParametric3D → .setX / .setY / .setZ · plotSurface → .setExpr / .setFn. All handles also have .sample() and .remove().
- Also pre-wired, do not re-declare: _labels, _syncLabels, animate, renderer, scene, camera, controls, d, aspect, setStandardView.

FIGURE RULES:
- Every visible element must be constructed as Three.js geometry (meshes, lines, points, sprites). Do NOT reproduce the figure as a texture, canvas drawing, or flat PlaneGeometry with the image drawn on it — pasting the original image onto a plane is never a valid solution.
- Keep the background white (#ffffff).
- The output should look recognizably like the source figure — same general geometry, viewpoint, labels, and proportions. It does not need to be a pixel-perfect same-size replacement.
- CAMERA / VIEW: camera pose is a standard default per projection mechanism, and PROJECTION TYPE in the user message gives the exact setCameraView call. Do not spend effort inferring exact angles from the source — spend it on ELEMENTS, geometry, and interactions. Align key visual anchors (object center, axes, labels) to similar relative positions as the source so the first frame is recognizable. You may adjust controls.target, object scale, and projection parameters; prefer setCameraView over setting camera.zoom directly, and if you do set zoom manually call camera.updateProjectionMatrix().
- Add ALL visible text labels with addLabel. Missing or wrong labels are a critical failure; match the source's font sizes and let placement reinforce depth.
- Interactions can be any type that serves the concept: sliders, buttons, panels, animations, step controls, hover/click, or direct 3D manipulation. Controls, panels, and UI affordances are welcome where they genuinely aid understanding — avoid decorative or redundant ones, but do not artificially restrict the type or amount of interaction.

ORDER OF WORK:
1) Settle the projection mechanism and pose from the plan BEFORE speccing any geometry — projection decides which edges stay parallel, which faces foreshorten, and what angle depth lines leave at.
2) Spec every element's Three.js primitive as one inline comment per element at the top of your JS block, e.g.
     // pinhole → SphereGeometry(0.07)  black
     // ray     → Line  dashed  grey
   Then build exactly that spec — do not deviate from it.
3) Build the static geometry. Preserve relative scale, spacing, depth ordering, and occlusion.
4) VERIFY before moving on: re-check what you built against GEOMETRY NOTES and the source image, element by element — position, orientation, proportions, and shape, not just presence. Fix any mismatch now; a generic-but-plausible arrangement that skips this check is the most common way geometry ends up wrong.
5) Then, in this order: setCameraView(...) → all labels → the plan's interactions.

userContent.text:
CONTEXT FROM TEXTBOOK:
This figure is an isometric visualization of a single layer's mapping, drawn as two flat square planes stacked one above the other and linked by dashed trajectories. Both planes are outlined in heavy dark gray and carry faint pale gray cross lines through their centers as axis guides. On the lower plane a broad cloud of red dots is scattered over the surface, densest near the middle and thinning toward the corners. Red dashed curves rise from each dot, converging as they climb, and land on the upper plane, where the points no longer fill an area at all: they are packed edge to edge along one short horizontal segment near the plane's back edge, forming a nearly solid red line. Light gray dashed lines trace the frame connecting the corners of the two planes, and a pair of gray arrowheads extends outward along the upper plane in line with the collapsed points. Holding both planes in the same orientation and scale makes the change of shape immediate, as a two-dimensional spread on the input is squeezed onto a one-dimensional locus on the output.

PROJECTION TYPE: axonometric
Use ordinary orthographic projection: setCameraView({ projection: 'orthographic', axisScreenAngles, heightFraction }). If the plan gives axis_screen_angles: null (a flat 2D plot/diagram), pass axisScreenAngles: null for a front-on view. Otherwise the plan does not measure per-figure angles — use a standard isometric pose: axisScreenAngles: { x: 30, z: 30 }. The source image is a PROJECTION of a 3D object: rebuild the true object — a rectangle stays a rectangle in world space — and let the camera do the projecting. Never bake the drawn parallelogram into the geometry, and never shear geometry. Omit zoom and call setCameraView after all geometry is added — the scaffold auto-fits from the projected bounding box.

ELEMENTS TO RECREATE IN 3D:
  - lower square plane drawn as a flat isometric diamond with heavy dark-gray outline (input space)
  - upper square plane, identical size and orientation, floating directly above the lower one (output space)
  - pale gray cross / axis guide lines through the center of each plane, running corner-to-corner mid-edge to mid-edge
  - broad cloud of ~200 red dots scattered across the lower plane, densest near the center, thinning toward the corners
  - collapsed red point set on the upper plane: the same dots packed edge-to-edge along one short horizontal segment near the plane's back edge, reading as a nearly solid red line
  - red dashed trajectory curves, one per point, rising from each lower-plane dot to its landing spot on the upper segment, converging as they climb
  - light gray dashed frame lines joining the four corners of the lower plane to the four corners of the upper plane
  - gray dashed vertical center line from the lower plane's front corner down/through the stack axis
  - small gray corner dots at the outer plane corners where the frame lines terminate
  - pair of gray arrowheads extending outward left and right along the upper plane, collinear with the collapsed red segment

GEOMETRY NOTES (world-space scale, color palette, and any formula/value needed for correctness — build to these so sizes, zoom, and colors match the source; do not guess dimensions the notes already specify):
Both planes are squares 6 × 6 world units lying in the XZ plane (+X screen-right-ish, +Z the receding diagonal, +Y screen-up). Lower plane centered at y = -3, upper plane at y = +3, identical orientation and scale so the shape change is the only difference. Plane outlines: heavy dark gray #3a3a3a, stroke ~3px. Axis guide crosses on each plane: pale gray #d8d8d8, two lines through the plane center joining opposite edge midpoints (they appear as an X in isometric). Input cloud: ~200 dots, radius ~0.07, fill red #f0262b at ~0.75 alpha, sampled as a 2D Gaussian centered on the lower-plane center with sigma ≈ 1.1 in both X and Z, clipped to the square (dense middle, sparse corners). Output locus: the SAME dots mapped to y = +3 with z fixed at z0 = -1.6 (near the back edge, about 27% in from the back) and x = 1.2 * tanh(0.9*x_in + 0.5*z_in), so x spans roughly -1.2 to +1.2 — a segment ~2.4 units long, points overlapping into a near-solid red bar. Trajectories: one dashed cubic per point from (x_in, -3, z_in) to its output, dash ~0.12/0.10, red #f0262b, alpha ramping from ~0.25 near the upper plane to ~0.85 near the lower plane; they bundle and converge as they rise. Gray dashed frame: four lines from each lower-plane corner to the corresponding upper-plane corner, #b0b0b0 dashed, with small gray dots (radius 0.08, #9a9a9a) at the left, right and front corners. A gray dashed vertical line runs down the front corner axis below the lower plane. Two gray arrowheads sit on the upper plane at x = ±3, z = z0, pointing outward along the collapsed segment's direction, joined to it by a faint gray dashed line. Background white.

DISCRETE CONTROLS (implement every one of these in #ui, each must work independently):
[
  {
    "id": "orbitScene",
    "type": "orbit",
    "teaches": "that the two planes are parallel sheets in depth and the red locus on the upper sheet really is one-dimensional — it stays a line from every viewing angle, while the lower cloud stays an area"
  },
  {
    "id": "mapProgress",
    "type": "slider",
    "teaches": "that the layer's action is a continuous squeeze: as the parameter advances, points travel along their dashed trajectories and the 2D spread contracts onto a 1D locus, with widely separated inputs arriving at nearly the same output",
    "label": "Mapping progress (input → output)",
    "range": [
      0,
      1,
      0.01
    ],
    "default": 0
  },
  {
    "id": "playMapping",
    "type": "animation",
    "teaches": "the overall dynamic of the layer — the red cloud lifts off the input plane, the trajectories converge, and the area collapses into a short segment on the output plane",
    "label": "Play layer mapping",
    "loop": false
  },
  {
    "id": "selectPoint",
    "type": "click",
    "teaches": "many-to-one collapse: clicking one output location lights up every input dot that lands there, showing that a whole region of the input plane is mapped onto a single spot of the output line",
    "label": "Trace a trajectory"
  }
]

DEMO STEPS (tween through these using goToStep(); each step drives the controls above):
[
  {
    "title": "Input distribution",
    "narration": "All red points sit on the lower plane, spread across two dimensions and densest near the center. Nothing has been mapped yet.",
    "state": {
      "mapProgress": 0
    }
  },
  {
    "title": "Mid-flight",
    "narration": "Scrubbing forward lifts every point along its dashed trajectory. The curves visibly converge — the cloud is already narrower in one direction than it was on the input plane.",
    "state": {
      "mapProgress": 0.5
    }
  },
  {
    "title": "Collapsed output",
    "narration": "At the output plane the cloud has no area left: every point lands on one short horizontal segment near the back edge. The layer has squeezed a 2D spread onto a 1D locus, so many different inputs share the same output.",
    "state": {
      "mapProgress": 1
    }
  }
]

CAMERA VIEW (framing only). Call setCameraView({ projection, ...these }) AFTER all geometry is added. Keep the projection MECHANISM from PROJECTION TYPE above (orthographic / sheared-oblique / perspective). For perspective these params set the pose (azimuth/elevation/roll); for the two parallel projections pose is a standard default (see PROJECTION TYPE above), and these params set only roll and framing (heightFraction):
{
  "rollDeg": 0,
  "heightFraction": 0.72
}

NOTES: Use an orthographic camera in a standard isometric pose so both planes read as congruent diamonds. Draw planes as line loops (no fill) so trajectories behind the upper plane remain visible; render trajectories with LineSegments + a dashed material and depthWrite false, sorting so upper-plane-crossing segments fade. Points as InstancedMesh of small spheres or as THREE.Points with a circular sprite; drive positions in a single interpolation buffer so mapProgress and playMapping share one update path (position = bezier(t) between input and output). The animation simply drives mapProgress 0→1 over ~2.5 s with ease-in-out. For selectPoint, do GPU-free picking against the 2D output x-coordinate: clicking anywhere on the upper segment selects all points whose output x is within a small tolerance and highlights their dots and dashed paths in saturated red while dimming the rest to ~0.12 alpha.

Follow the interaction plan above.

Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:600;font-size:13px;margin-bottom:2px">One layer: a 2-D spread squeezed onto a 1-D locus</div>
<div style="color:#555;line-height:1.4">Lower plane = input space, upper plane = output space. Drag the canvas to orbit — the red output stays a line from every angle.</div>

<label style="margin-top:6px">Mapping progress (input → output): <span id="progVal" style="font-family:monospace">0.00</span>
  <input id="mapProgress" type="range" min="0" max="1" step="0.01" value="0">
</label>
<button id="playMapping">▶ Play layer mapping</button>

<div style="font-weight:600;margin-top:8px">Demo steps</div>
<button id="step0">1 · Input distribution</button>
<button id="step1">2 · Mid-flight</button>
<button id="step2">3 · Collapsed output</button>
<div id="narration" style="color:#333;line-height:1.4;border-left:3px solid #f0262b;padding-left:6px;margin-top:4px">
  All red points sit on the lower plane, spread across two dimensions and densest near the center. Nothing has been mapped yet.
</div>

<div style="font-weight:600;margin-top:8px">Trace a trajectory</div>
<div id="selInfo" style="color:#333;line-height:1.4">Click anywhere on the upper plane, along the red bar: every input dot that lands at that spot lights up.</div>
<button id="clearSel">Clear selection</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* Element spec (build exactly this):
   lower plane outline (y=-3, 6x6 XZ)   → 4 × BoxGeometry(L,0.05,0.05)   #3a3a3a
   upper plane outline (y=+3, 6x6 XZ)   → 4 × BoxGeometry(L,0.05,0.05)   #3a3a3a
   axis cross guides on each plane      → 2 × Line (LineBasicMaterial)   #d8d8d8
   input cloud (200 gaussian dots)      → InstancedMesh(SphereGeometry(0.07)) #f0262b
   output locus (same dots at y=+3)     → same InstancedMesh at t=1
   trajectories (one dashed cubic/point)→ LineSegments (manual dashes, vertexColors) #f0262b
   frame lines corner→corner            → LineSegments (manual dashes)    #b0b0b0
   front-corner vertical extension      → LineSegments (manual dashes)    #b0b0b0
   corner dots (left/right/front)       → 3 × SphereGeometry(0.08)        #9a9a9a
   arrowheads at x=±3 on upper plane    → 2 × ConeGeometry(0.12,0.30)     #9a9a9a
   arrow guide line through locus       → LineSegments (manual dashes)    #c8c8c8
   pick plane at y=+3 (invisible)       → Mesh(PlaneGeometry) opacity 0
*/

const HALF = 3;            // half side of each square plane
const Y_IN = -3, Y_OUT = 3;
const Z0 = -1.6;           // output locus depth
const DARK = 0x3a3a3a, PALE = 0xd8d8d8, GRAY = 0xb0b0b0, GRAYDOT = 0x9a9a9a;
const RED = new THREE.Color(0xf0262b);
const WHITE = new THREE.Color(0xffffff);

/* ── helpers ─────────────────────────────────────────────────────────── */
function thickEdge(p, q, color, thick) {
  const dx = q.x - p.x, dy = q.y - p.y, dz = q.z - p.z;
  const L = Math.hypot(dx, dy, dz);
  const m = new THREE.Mesh(new THREE.BoxGeometry(L, thick, thick),
    new THREE.MeshBasicMaterial({ color }));
  m.position.set((p.x + q.x) / 2, (p.y + q.y) / 2, (p.z + q.z) / 2);
  m.rotation.y = Math.atan2(-dz, dx);
  scene.add(m);
  return m;
}
function dashPush(arr, a, b, dash, gap) {
  const dir = b.clone().sub(a);
  const len = dir.length();
  if (len < 1e-6) return;
  dir.normalize();
  let s = 0;
  while (s < len) {
    const e = Math.min(s + dash, len);
    arr.push(a.x + dir.x * s, a.y + dir.y * s, a.z + dir.z * s,
             a.x + dir.x * e, a.y + dir.y * e, a.z + dir.z * e);
    s = e + gap;
  }
}
function dashedLines(arr, color, opacity) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  const m = new THREE.LineSegments(g, new THREE.LineBasicMaterial({
    color, transparent: true, opacity: opacity ?? 1, depthWrite: false
  }));
  scene.add(m);
  return m;
}
function planeCorners(y) {
  return [
    new THREE.Vector3(-HALF, y, -HALF),
    new THREE.Vector3(HALF, y, -HALF),
    new THREE.Vector3(HALF, y, HALF),
    new THREE.Vector3(-HALF, y, HALF)
  ];
}

/* ── the two planes ──────────────────────────────────────────────────── */
[Y_IN, Y_OUT].forEach(y => {
  const c = planeCorners(y);
