const HALF = 3;                 // half side of each square plane
const Y_IN = -3, Y_OUT = 3;
const Z0 = -1.6;                // depth of the collapsed output locus
const DARK = 0x3a3a3a, PALE = 0xd5d5d5, GRAY = 0xa8a8a8, GRAYDOT = 0x9a9a9a;
const RED = new THREE.Color(0xee2222);
const WHITE = new THREE.Color(0xffffff);
const OUT_AMP = 2.35;           // half-length of the collapsed red bar

/* ── helpers ─────────────────────────────────────────────────────────── */
function thickEdge(p, q, color, thick) {
  const dx = q.x - p.x, dy = q.y - p.y, dz = q.z - p.z;
  const L = Math.hypot(dx, dy, dz);
  const m = new THREE.Mesh(new THREE.BoxGeometry(L, thick, thick),
    new THREE.MeshBasicMaterial({ color }));
  m.position.set((p.x + q.x) / 2, (p.y + q.y) / 2, (p.z + q.z) / 2);
  m.rotation.y = Math.atan2(-dz, dx);
  scene.add(m);
  return m;
}
function dashPush(arr, a, b, dash, gap) {
  const dir = b.clone().sub(a);
  const len = dir.length();
  if (len < 1e-6) return;
  dir.normalize();
  let s = 0;
  while (s < len) {
    const e = Math.min(s + dash, len);
    arr.push(a.x + dir.x * s, a.y + dir.y * s, a.z + dir.z * s,
             a.x + dir.x * e, a.y + dir.y * e, a.z + dir.z * e);
    s = e + gap;
  }
}
function dashedLines(arr, color, opacity) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  const m = new THREE.LineSegments(g, new THREE.LineBasicMaterial({
    color, transparent: true, opacity: opacity ?? 1, depthWrite: false
  }));
  scene.add(m);
  return m;
}
function planeCorners(y) {
  return [
    new THREE.Vector3(-HALF, y, -HALF),   // back
    new THREE.Vector3(HALF, y, -HALF),    // screen-right
    new THREE.Vector3(HALF, y, HALF),     // front (screen-bottom)
    new THREE.Vector3(-HALF, y, HALF)     // screen-left
  ];
}

/* ── the two planes ──────────────────────────────────────────────────── */
[Y_IN, Y_OUT].forEach(y => {
  const c = planeCorners(y);
  for (let i = 0; i < 4; i++) thickEdge(c[i], c[(i + 1) % 4], DARK, 0.06);
  const guideMat = new THREE.LineBasicMaterial({ color: PALE });
  const g1 = new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(-HALF, y, 0), new THREE.Vector3(HALF, y, 0)]);
  const g2 = new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0, y, -HALF), new THREE.Vector3(0, y, HALF)]);
  scene.add(new THREE.Line(g1, guideMat));
  scene.add(new THREE.Line(g2, guideMat.clone()));
});

/* ── gray dashed frame: plane corners converging onto the output segment ── */
const ARROW_X = HALF - 0.25;
{
  const arr = [];
  const Lc = new THREE.Vector3(-HALF, Y_IN, HALF);   // screen-left corner (lower)
  const Rc = new THREE.Vector3(HALF, Y_IN, -HALF);   // screen-right corner (lower)
  const Lt = new THREE.Vector3(-ARROW_X, Y_OUT, Z0);
  const Rt = new THREE.Vector3(ARROW_X, Y_OUT, Z0);
  dashPush(arr, Lc, Lt, 0.26, 0.20);
  dashPush(arr, Rc, Rt, 0.26, 0.20);
  // long converging tails: continue well past the lower corners and their dots
  const EXT = 1.45;
  dashPush(arr, Lc, Lc.clone().add(Lc.clone().sub(Lt).normalize().multiplyScalar(EXT)), 0.26, 0.20);
  dashPush(arr, Rc, Rc.clone().add(Rc.clone().sub(Rt).normalize().multiplyScalar(EXT)), 0.26, 0.20);
  // front-corner vertical: upper plane front corner → lower plane front corner → below
  dashPush(arr, new THREE.Vector3(HALF, Y_OUT, HALF),
                new THREE.Vector3(HALF, Y_IN, HALF), 0.26, 0.20);
  dashPush(arr, new THREE.Vector3(HALF, Y_IN, HALF),
                new THREE.Vector3(HALF, Y_IN - 1.9, HALF), 0.26, 0.20);
  dashedLines(arr, GRAY, 0.95);

  const cornerDotGeo = new THREE.SphereGeometry(0.095, 14, 12);
  const cornerDotMat = new THREE.MeshBasicMaterial({ color: GRAYDOT });
  [[-HALF, Y_IN, HALF], [HALF, Y_IN, -HALF], [HALF, Y_IN - 1.9, HALF]].forEach(p => {
    const s = new THREE.Mesh(cornerDotGeo, cornerDotMat);
    s.position.set(p[0], p[1], p[2]);
    scene.add(s);
  });
}

/* ── arrowheads + faint guide line along the collapsed segment ───────── */
{
  const arr = [];
  dashPush(arr, new THREE.Vector3(-ARROW_X, Y_OUT, Z0),
                new THREE.Vector3(ARROW_X, Y_OUT, Z0), 0.20, 0.16);
  dashedLines(arr, 0xc4c4c4, 0.9);
  const coneGeo = new THREE.ConeGeometry(0.13, 0.32, 14);
  const coneMat = new THREE.MeshBasicMaterial({ color: GRAYDOT });
  [1, -1].forEach(s => {
    const cone = new THREE.Mesh(coneGeo, coneMat);
    cone.position.set(s * (HALF - 0.1), Y_OUT, Z0);
    cone.rotation.z = -s * Math.PI / 2;
    scene.add(cone);
  });
}

/* ── the point cloud: wide gaussian on the input plane ───────────────── */
function mulberry32(a) {
  return function () {
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(20240923);
function gauss() {
  let u = 0, v = 0;
  while (u === 0) u = rnd();
  while (v === 0) v = rnd();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
const N = 240, SIG = 1.48, CLIP = 2.78;
const inX = new Float32Array(N), inZ = new Float32Array(N);
const outX = new Float32Array(N);
for (let i = 0; i < N; i++) {
  let x, z;
  do { x = gauss() * SIG; } while (Math.abs(x) > CLIP);
  do { z = gauss() * SIG; } while (Math.abs(z) > CLIP);
  inX[i] = x; inZ[i] = z;
  outX[i] = OUT_AMP * Math.tanh(0.85 * (0.6 * x + 0.4 * z));   // 2-D → 1-D squeeze
}

/* near-linear cubic rays (controls sit close to the straight-line thirds) */
const P0 = [], P1 = [], P2 = [], P3 = [];
for (let i = 0; i < N; i++) {
  const a = new THREE.Vector3(inX[i], Y_IN, inZ[i]);
  const b = new THREE.Vector3(outX[i], Y_OUT, Z0);
  P0.push(a);
  P1.push(new THREE.Vector3(a.x * 0.82 + b.x * 0.18, Y_IN + 2.0, a.z * 0.82 + b.z * 0.18));
  P2.push(new THREE.Vector3(a.x * 0.16 + b.x * 0.84, Y_OUT - 2.0, a.z * 0.16 + b.z * 0.84));
  P3.push(b);
}
const _b = new THREE.Vector3();
function bez(i, t, out) {
  const u = 1 - t, a = u * u * u, b = 3 * u * u * t, c = 3 * u * t * t, dd = t * t * t;
  out.set(
    a * P0[i].x + b * P1[i].x + c * P2[i].x + dd * P3[i].x,
    a * P0[i].y + b * P1[i].y + c * P2[i].y + dd * P3[i].y,
    a * P0[i].z + b * P1[i].z + c * P2[i].z + dd * P3[i].z
  );
  return out;
}

/* ── moving dots + persistent collapsed-output ghost bar ─────────────── */
const dotGeoShared = new THREE.SphereGeometry(0.09, 12, 10);
const dots = new THREE.InstancedMesh(
  dotGeoShared,
  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 1.0, depthWrite: false }),
  N
);
dots.renderOrder = 4;
scene.add(dots);

const ghost = new THREE.InstancedMesh(
  dotGeoShared,
  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 1.0, depthWrite: false }),
  N
);
ghost.renderOrder = 3;
scene.add(ghost);

const _dummy = new THREE.Object3D();
const _col = new THREE.Color();
for (let i = 0; i < N; i++) {
  _dummy.position.set(outX[i], Y_OUT, Z0);
  _dummy.scale.setScalar(1);
  _dummy.updateMatrix();
  ghost.setMatrixAt(i, _dummy.matrix);
}
ghost.instanceMatrix.needsUpdate = true;

/* ── trajectories: dashed, double-stranded, saturated red well past midpoint ── */
const S = 49;
const segKeep = [];
for (let j = 0; j < S - 1; j++) if (j % 4 < 2) segKeep.push(j);
const STRAND = [-1, 1];
const SOX = 0.016, SOZ = -0.016;                    // screen-horizontal offset
const VPT = segKeep.length * 2 * STRAND.length;     // vertices per trajectory
const trajPos = new Float32Array(N * VPT * 3);
const trajBase = new Float32Array(N * VPT * 3);
const trajCol = new Float32Array(N * VPT * 3);
function rayAlpha(u) {
  // full saturation below and a little past the upper plane crossing, then fade
  if (u < 0.55) return 1.0;
  const k = (u - 0.55) / 0.45;
  return 1.0 - 0.62 * Math.pow(k, 1.3);
}
{
  const pa = new THREE.Vector3(), pb = new THREE.Vector3();
  let v = 0;
  for (let i = 0; i < N; i++) {
    for (const sgn of STRAND) {
      const ox = sgn * SOX, oz = sgn * SOZ;
      for (const j of segKeep) {
        bez(i, j / (S - 1), pa);
        bez(i, (j + 1) / (S - 1), pb);
        const u = (j + 0.5) / (S - 1);
