        trajBase[v * 3] = _col.r; trajBase[v * 3 + 1] = _col.g; trajBase[v * 3 + 2] = _col.b;
        v++;
        trajPos[v * 3] = pb.x + ox; trajPos[v * 3 + 1] = pb.y; trajPos[v * 3 + 2] = pb.z + oz;
        trajBase[v * 3] = _col.r; trajBase[v * 3 + 1] = _col.g; trajBase[v * 3 + 2] = _col.b;
        v++;
      }
    }
  }
  trajCol.set(trajBase);
}
const trajGeo = new THREE.BufferGeometry();
trajGeo.setAttribute('position', new THREE.BufferAttribute(trajPos, 3));
trajGeo.setAttribute('color', new THREE.BufferAttribute(trajCol, 3));
const traj = new THREE.LineSegments(trajGeo, new THREE.LineBasicMaterial({
  vertexColors: true, transparent: true, opacity: 0.98, depthWrite: false
}));
traj.renderOrder = 1;
scene.add(traj);

/* ── label leader line for the collapsed locus ───────────────────────── */
const LEAD_A = new THREE.Vector3(-1.35, Y_OUT, Z0);
const LEAD_B = new THREE.Vector3(-2.55, Y_OUT + 1.15, Z0 - 0.25);
