pickPlane.position.y = Y_OUT;
scene.add(pickPlane);

/* ── state + update ──────────────────────────────────────────────────── */
let progress = 0;
const selected = new Uint8Array(N);
let hasSelection = false;

function updateDots() {
  for (let i = 0; i < N; i++) {
    bez(i, progress, _b);
