addLabel('input space — 2-D spread', new THREE.Vector3(-1.5, Y_IN, HALF),
  { color: '#6a6a6a', fontSize: '11px', offset: [-34, 24] });
addLabel('output space', new THREE.Vector3(-HALF, Y_OUT, 0),
  { color: '#6a6a6a', fontSize: '11px', offset: [-40, -2] });

registerInteractive(ghost, {
  title: 'The collapsed 1-D locus',
  tooltip: 'The whole 2-D cloud lands on this one segment',
  body: 'Every one of the 240 input points is mapped onto this single horizontal segment. The layer has destroyed one degree of freedom: the output set has zero area, so infinitely many distinct inputs share the same output.'
});
registerInteractive(dots, {
  title: 'Input distribution',
  tooltip: 'A 2-D cloud of inputs',
  body: 'The input points fill both directions of the lower plane. Scrub "Mapping progress" to watch them ride their dashed trajectories up to the output plane.'
});

/* ── controls ────────────────────────────────────────────────────────── */
const slider = document.getElementById('mapProgress');
const progVal = document.getElementById('progVal');
const narration = document.getElementById('narration');
const selInfo = document.getElementById('selInfo');
const ghostBox = document.getElementById('showGhost');

ghostBox.addEventListener('change', () => { ghost.visible = ghostBox.checked; });

function setProgress(p, fromSlider) {
  progress = Math.max(0, Math.min(1, p));
